// bridge/python.ts - the Python ML provider's TypeScript side.
//
// Python (python/xrgen) owns ML-flavored generation: latent sampling, the
// seeded style MLP, biome mixture weights. Two ways TS talks to it:
//
//  1. TsMlProvider - a pure-TS mirror of the Python math (forward pass,
//     latent sampling). Used at runtime with style weights generated by
//     Python (demo/public/gen/python-style.json). The mirror is exact:
//     test/python-mirror checks it against the real Python output.
//  2. PythonBridge - spawns `python3 -m xrgen.bridge` and speaks the
//     JSON-lines protocol. Node/tooling only (browsers can't spawn
//     processes); this is also the reference client for the C++ and C#
//     bridges, which speak the same protocol.

export interface MlWeights {
  arch: [number, number, number];
  w1: number[][];
  b1: number[];
  w2: number[][];
  b2: number[];
  style_seed: number;
}

/** ML generation surface. Python implements it; TS mirrors the pure math. */
export interface MlProvider {
  readonly languageTag: string;
  /** Deterministic latent vector (Box-Muller normals over SplitMix64). */
  latent(seed: number, dim: number): number[];
  /** One forward pass of the style MLP. x = [height, u, v], out in (0,1). */
  stylizeForward(x: [number, number, number], w: MlWeights): number;
}

const M64 = (1n << 64n) - 1n;

function splitmix64Next(state: bigint): [bigint, number] {
  state = (state + 0x9e3779b97f4a7c15n) & M64;
  let z = state;
  z = (((z ^ (z >> 30n)) * 0xbf58476d1ce4e5b9n) & M64);
  z = ((z ^ (z >> 27n)) * 0x94d049bb133111ebn) & M64;
  z = z ^ (z >> 31n);
  return [state, Number(z) / 18446744073709551616];
}

function tanh(x: number): number {
  const e = Math.exp(2 * x);
  return (e - 1) / (e + 1);
}

function sigmoid(x: number): number {
  if (x >= 0) return 1 / (1 + Math.exp(-x));
  const e = Math.exp(x);
  return e / (1 + e);
}

/** Pure-TS mirror of python/xrgen. languageTag stays honest: the math and
 *  the weights come from Python; this just evaluates them. */
export class TsMlProvider implements MlProvider {
  readonly languageTag = 'Python';

  latent(seed: number, dim: number): number[] {
    // One normal per two uniforms, cos only - exactly like Rng.normal()
    // in python/xrgen/rng.py. Do not "optimize" this to use the sin half.
    let s = (BigInt(seed) ^ 0x1a7e57n) & M64;
    const out: number[] = [];
    for (let i = 0; i < dim; i++) {
      let u1: number; let u2: number; let st: bigint;
      [st, u1] = splitmix64Next(s); s = st;
      u1 = Math.max(u1, 1e-12);
      [st, u2] = splitmix64Next(s); s = st;
      out.push(Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2));
    }
    return out;
  }

  stylizeForward(x: [number, number, number], w: MlWeights): number {
    const hidden: number[] = [];
    for (let i = 0; i < 6; i++) {
      hidden.push(tanh(
        w.w1[i][0] * x[0] + w.w1[i][1] * x[1] + w.w1[i][2] * x[2] + w.b1[i],
      ));
    }
    let y = w.b2[0];
    for (let i = 0; i < 6; i++) y += w.w2[0][i] * hidden[i];
    return sigmoid(y);
  }
}

/** Load style weights generated by the Python provider
 *  (regenerate: python3 demo/scripts/gen-style-params.py). */
export async function loadStyleWeights(url: string): Promise<MlWeights> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`style weights not found: ${url}`);
  const doc = (await res.json()) as MlWeights | { weights: MlWeights };
  return 'weights' in doc ? doc.weights : doc;
}
